command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "ca2928e28623ee8813d4077eb551e8df258d8a43") { throw "main moved" }

git -C $env:GITHUB_WORKSPACE push origin --delete work/content-encodings
if ($LASTEXITCODE -ne 0) { throw "content encoding branch cleanup failed" }

Write-Host "CONTENT_ENCODING_WORK_BRANCH_DELETED"
